    const closedComps = new Set();
    for (let c = 0; c < M.nComp; c++) if (!openComp.has(c)) closedComps.add(c);
    await say('Writing STEP', 0.88);
    const model = { verts: topo.verts, edges: topo.edges, faces, closedComps };
