$('modeFaces').onclick = () => { state.mode = 'faces'; applyMode(); };
$('modeMesh').onclick = () => { state.mode = 'mesh'; applyMode(); };
$('fit').onclick = fitView;
// re-colour on theme change
const mq = window.matchMedia('(prefers-color-scheme: dark)');
